package org.l2jmobius.gameserver.managers.phantom;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.io.*;import java.util.concurrent.ConcurrentHashMap;import java.util.logging.*;
import org.l2jmobius.gameserver.entity.actor.Player;import org.l2jmobius.gameserver.data.sql.CharInfoTable;
/** Persistent selected character profiles, not class requests: group recall never creates replacements. */
public final class PersonalSavedParty {
 static final Logger LOG=Logger.getLogger(PersonalSavedParty.class.getName());static final Store STORE=new Store(Path.of("data/L2HubSavedPersonalParties.properties"));static final Map<Integer,String> VIEWS=new ConcurrentHashMap<>();
 private PersonalSavedParty(){}
 static String key(PhantomTemplate t){var p=t==null?null:PersonalCompanionNames.named(t.getName());return p==null?null:p.key();}
 static PhantomTemplate template(String key){return PhantomData.getInstance().getTemplate(PersonalCompanionNames.name(key));}
 static String reservation(Player p,PhantomTemplate t){String key=key(t);int owner=key==null?0:STORE.owner(key);return owner>0&&owner!=p.getObjectId()?"Этот помощник закреплён за сохранённой пачкой другого игрока.":null;}
 static boolean open(Player p){return VIEWS.containsKey(p.getObjectId());}static void close(Player p){VIEWS.remove(p.getObjectId());}
 static String afterSummon(Player p,PhantomTemplate t){String key=key(t);if(key==null||!PersonalCompanions.personal(t))return null;try{List<String> list=STORE.get(p.getObjectId());if(list.contains(key)||list.size()>=8)return null;List<String> next=new ArrayList<>(list);next.add(key);STORE.set(p.getObjectId(),next);return null;}catch(IOException e){LOG.log(Level.WARNING,"Helper summoned but saved party could not be updated",e);return "Помощник призван, но состав не сохранился; подробности в журнале.";}}
 static String add(Player p,String base){if(PersonalBattleCatalog.PROFILES.stream().noneMatch(x->x.key().equals(base))&&!base.equals("buffer"))return "Нет такого класса.";
  synchronized(PersonalCompanionPool.class){List<String> members=STORE.get(p.getObjectId());if(members.size()>=8)return "В составе уже восемь помощников.";var cm=PhantomCompanionManager.getInstance();try{var t=PersonalCompanionPool.acquire(p,base,x->{String k=key(x);return k!=null&&!members.contains(k)&&reservation(p,x)==null&&(cm.isOwner(p,x)||PersonalCompanionPool.eligible(p,x));},name->PhantomData.getInstance().getTemplate(name)==null&&!CharInfoTable.getInstance().doesCharNameExist(name));List<String> next=new ArrayList<>(members);next.add(key(t));STORE.set(p.getObjectId(),next);return null;}catch(IOException|IllegalArgumentException e){LOG.log(Level.WARNING,"Saved party selection failed",e);return "Не удалось сохранить выбранного помощника; подробности в журнале.";}}
 }
 static String handle(Player p,String action){PersonalBattleCatalog.back(p);if(action==null)action="edit";try{
  if(action.equals("back")){close(p);return null;}
  if(Set.of("edit","mage","warrior").contains(action)){VIEWS.put(p.getObjectId(),action);return null;}
  if(action.startsWith("add_")){String result=add(p,action.substring(4));VIEWS.put(p.getObjectId(),"edit");return result;}
  if(action.startsWith("del_")){int index=Integer.parseInt(action.substring(4));List<String> list=new ArrayList<>(STORE.get(p.getObjectId()));if(index<0||index>=list.size())return "Нет такого участника.";list.remove(index);STORE.set(p.getObjectId(),list);return null;}
  if(action.equals("save")){if(!p.isInParty())return "Сейчас ты не в пати.";List<String> list=new ArrayList<>();var cm=PhantomCompanionManager.getInstance();for(Player member:p.getParty().getMembers()){var t=PhantomData.getInstance().getTemplate(member.getName());if(t!=null&&PersonalCompanions.personal(t)&&cm.isOwner(p,t)&&key(t)!=null)list.add(key(t));}if(list.isEmpty())return "В пати нет твоих персональных помощников.";STORE.set(p.getObjectId(),list);VIEWS.put(p.getObjectId(),"edit");return "Текущая пачка сохранена.";}
  if(Set.of("summon","dismiss","clan").contains(action))return batch(p,action);
  return "Неизвестное действие пачки.";
 }catch(IOException|IllegalArgumentException e){LOG.log(Level.WARNING,"Saved party action failed",e);return "Не удалось изменить сохранённый состав; подробности в журнале.";}}
 static String batch(Player p,String action){List<String> list=STORE.get(p.getObjectId());if(list.isEmpty())return "Сначала выбери состав или сохрани текущую пати.";var cm=PhantomCompanionManager.getInstance();if(action.equals("summon")&&p.isInParty()&&!p.getParty().isLeader(p))return "Призвать пачку может лидер пати.";int ok=0,already=0;List<String> errors=new ArrayList<>();
  synchronized(cm){for(String key:list){PhantomTemplate t=template(key);if(t==null){errors.add("Профиль "+key+" недоступен");continue;}String error=null;
   if(action.equals("summon")){if(cm.isPartiedWith(p,t)){already++;continue;}if(p.isInParty()&&p.getParty().getMemberCount()>=9){errors.add("Нет свободных мест в пати");break;}error=PersonalBattleCatalog.summon(p,t);}
   else if(action.equals("dismiss")){if(!cm.isOwner(p,t)||PhantomManager.getInstance().getPhantom(t)==null){already++;continue;}error=cm.dismiss(p,t,true);}
   else {Player actor=PhantomManager.getInstance().getPhantom(t);if(actor==null||!cm.isOwner(p,t))error="Сначала призови "+t.getName();else error=PersonalCompanionClans.enroll(p,actor);}
   if(error==null)ok++;else errors.add(t.getName()+": "+error);
  }}
  VIEWS.put(p.getObjectId(),"edit");String text=(action.equals("summon")?"Призвано: ":action.equals("dismiss")?"Отозвано: ":"Принято в клан: ")+ok+"; уже в нужном состоянии: "+already+".";if(!errors.isEmpty())text+=" "+errors.getFirst()+(errors.size()>1?" (ещё "+(errors.size()-1)+")":"");return text;
 }
 static String button(String title,String bypass,String action,int width){return PersonalBattleCatalog.button(title,bypass,"squad",action,width);}
 static String summary(Player p,String bypass){return "<font color=LEVEL>Моя пачка ("+STORE.get(p.getObjectId()).size()+"/8)</font><br>"+button("Вызвать пачку",bypass,"summon",180)+"<br>"+button("Отозвать пачку",bypass,"dismiss",180)+"<br>"+button("Состав пачки",bypass,"edit",180)+"<br><br>";}
 static String esc(String s){return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}
 static String board(Player p,String bypass){PhantomData.getInstance();String mode=VIEWS.getOrDefault(p.getObjectId(),"edit");StringBuilder b=new StringBuilder("<font color=LEVEL>Моя сохранённая пачка</font><br><br>");
  if(mode.equals("mage")||mode.equals("warrior")){for(var profile:PersonalBattleCatalog.PROFILES)if(profile.family().equals(mode))b.append(button(profile.label(),bypass,"add_"+profile.key(),180)).append("<br>");if(mode.equals("mage"))b.append(button("Баффер",bypass,"add_buffer",180)).append("<br>");return b.append("<font color=808080>Выбор добавляет отдельного персонажа в состав.<br>Призовёшь всех одной кнопкой.</font><br>").append(button("К составу",bypass,"edit",180)).toString();}
  List<String> list=STORE.get(p.getObjectId());if(list.isEmpty())b.append("Состав пока пуст.<br><br>");for(int i=0;i<list.size();i++){var t=template(list.get(i));String label=t==null?list.get(i):t.getName()+" — "+Optional.ofNullable(PersonalBattleCatalog.caption(t)).orElse("баффер");b.append("<table width=280><tr><td width=205>").append(esc(label)).append("</td><td>").append(button("Убрать",bypass,"del_"+i,65)).append("</td></tr></table>");}
  b.append("<br>").append(button("Добавить воина",bypass,"warrior",180)).append("<br>").append(button("Добавить мага/хилера",bypass,"mage",180)).append("<br>").append(button("Сохранить текущую пати",bypass,"save",200)).append("<br><br>").append(button("Вызвать пачку",bypass,"summon",180)).append("<br>").append(button("Отозвать пачку",bypass,"dismiss",180)).append("<br>").append(button("Принять пачку в клан",bypass,"clan",200)).append("<br><font color=808080>Те же персонажи: клан, имена и прогресс сохраняются.<br>В пати всего девять мест, включая игроков.<br>Удаление из состава не удаляет персонажа.</font><br>").append(button("Назад",bypass,"back",120));return b.toString();
 }
 static final class Store {
  final Path path;final Map<Integer,List<String>> rows=new LinkedHashMap<>();Store(Path p){path=p;if(!Files.exists(p))return;Properties props=new Properties();try(var reader=Files.newBufferedReader(p,StandardCharsets.UTF_8)){props.load(reader);}catch(IOException e){throw new IllegalStateException(e);}Set<String> all=new HashSet<>();for(String key:props.stringPropertyNames()){int id=Integer.parseInt(key);List<String> members=props.getProperty(key).isBlank()?List.of():List.of(props.getProperty(key).split(";"));validate(members);if(id<=0||members.stream().anyMatch(x->!all.add(x)))throw new IllegalStateException("Invalid/repeated saved-party reservation");rows.put(id,members);}}
  static void validate(List<String> members){if(members.size()>8||new HashSet<>(members).size()!=members.size()||members.stream().anyMatch(x->!x.matches("[a-z0-9_.-]+")))throw new IllegalArgumentException("Invalid personal party members");}
  synchronized List<String> get(int owner){return rows.getOrDefault(owner,List.of());}synchronized int owner(String key){return rows.entrySet().stream().filter(x->x.getValue().contains(key)).mapToInt(Map.Entry::getKey).findFirst().orElse(0);}
  synchronized void set(int owner,List<String> members)throws IOException {validate(members);for(String key:members)if(owner(key)>0&&owner(key)!=owner)throw new IOException("Helper already belongs to another saved party");Map<Integer,List<String>> next=new LinkedHashMap<>(rows);next.put(owner,List.copyOf(members));Properties props=new Properties();for(var entry:next.entrySet())props.setProperty(Integer.toString(entry.getKey()),String.join(";",entry.getValue()));Files.createDirectories(path.toAbsolutePath().getParent());Path temp=path.resolveSibling(path.getFileName()+".tmp");try(var out=Files.newBufferedWriter(temp,StandardCharsets.UTF_8)){props.store(out,"Persistent personal party composition; character IDs/clans are stored separately");}try{Files.move(temp,path,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(temp,path,StandardCopyOption.REPLACE_EXISTING);}rows.clear();rows.putAll(next);}
 }
}
